import{_ as e,o as r,c as n,a2 as t}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"kiwa v1.36 released — Search 深化 II (@kiwa-test/search v0.3.0 + 8 axis advanced search + 縦深化 pair 第 8 pair 連続化 + 3-stage 拡張 pattern 3 例目)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.36/zenn-article.md","filePath":"announcements/v1.36/zenn-article.md"}'),i={name:"announcements/v1.36/zenn-article.md"};function s(o,a,c,d,h,l){return r(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="kiwa-v1-36-released-—-search-深化-ii-kiwa-test-search-v0-3-0-8-axis-advanced-search-縦深化-pair-第-8-pair-連続化-3-stage-拡張-pattern-3-例目" tabindex="-1">kiwa v1.36 released — Search 深化 II (@kiwa-test/search v0.3.0 + 8 axis advanced search + 縦深化 pair 第 8 pair 連続化 + 3-stage 拡張 pattern 3 例目) <a class="header-anchor" href="#kiwa-v1-36-released-—-search-深化-ii-kiwa-test-search-v0-3-0-8-axis-advanced-search-縦深化-pair-第-8-pair-連続化-3-stage-拡張-pattern-3-例目" aria-label="Permalink to &quot;kiwa v1.36 released — Search 深化 II (@kiwa-test/search v0.3.0 + 8 axis advanced search + 縦深化 pair 第 8 pair 連続化 + 3-stage 拡張 pattern 3 例目)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li><strong>kiwa v1.36 released</strong> — Search 深化 II milestone</li><li><strong><code>@kiwa-test/search</code> v0.2.0 → v0.3.0 minor bump</strong> — 8 axis advanced search semantics + real driver env-gate + 4 provider × 8 axis neutral state machine 追加</li><li><strong>8 axis semantics</strong> = Vector search + Semantic search + Faceted advanced + Geo search + Relevance tuning + Synonym/stemming advanced + Index management advanced + Query DSL/aggregation advanced</li><li><strong>3 dogfood app v2 / 新規</strong> — search-vector-app v2 + search-faceted-geo-app v2 + search-opensearch-app 新規</li><li><strong>縦深化 pair pattern 第 8 pair 連続化</strong> — Search pair (v1.14→v1.15→v1.36)</li><li><strong>14 milestone 連続 snippet validation streak</strong> (v1.23-v1.36)</li><li>v1.11 以降 26 milestone 連続完遂</li></ul><h2 id="v1-36-が解決したい問題-—-search-production-semantics-の-testing-gap" tabindex="-1">v1.36 が解決したい問題 — Search production semantics の testing gap <a class="header-anchor" href="#v1-36-が解決したい問題-—-search-production-semantics-の-testing-gap" aria-label="Permalink to &quot;v1.36 が解決したい問題 — Search production semantics の testing gap&quot;">​</a></h2><p>v1.14 で <code>@kiwa-test/search</code> v0.1 (Meilisearch / Algolia / Typesense の 3 provider を統一 mock として提供する in-memory search envelope) を land、 v1.15 で search v0.2 に拡張した時点で、 kiwa は query / index / search / facet / typo tolerance の base semantics までは cover していた.</p><p>v1.36 は vector retrieval、 semantic rerank、 nested and hierarchical facet、 geo polygon / isochrone、 BM25 / TF-IDF / custom ranking、 synonym and stemming、 sharding and rolling reindex、 nested query and aggregation を 8 axis advanced search semantics として追加する深化 milestone.</p><h2 id="v1-36-で追加した-8-axis-advanced-search-semantics" tabindex="-1">v1.36 で追加した 8 axis advanced search semantics <a class="header-anchor" href="#v1-36-で追加した-8-axis-advanced-search-semantics" aria-label="Permalink to &quot;v1.36 で追加した 8 axis advanced search semantics&quot;">​</a></h2><h3 id="_1-vector-search" tabindex="-1">1. Vector search <a class="header-anchor" href="#_1-vector-search" aria-label="Permalink to &quot;1. Vector search&quot;">​</a></h3><p>kNN + HNSW + IVF + flat vector index + hybrid fusion + reciprocal rank fusion + weighted fusion + recall@k.</p><h3 id="_2-semantic-search" tabindex="-1">2. Semantic search <a class="header-anchor" href="#_2-semantic-search" aria-label="Permalink to &quot;2. Semantic search&quot;">​</a></h3><p>embedding query understanding + cross encoder rerank + semantic rewrite + query expansion.</p><h3 id="_3-faceted-advanced" tabindex="-1">3. Faceted advanced <a class="header-anchor" href="#_3-faceted-advanced" aria-label="Permalink to &quot;3. Faceted advanced&quot;">​</a></h3><p>nested facet + hierarchical facet + tree traversal facet + facet count stability.</p><h3 id="_4-geo-search" tabindex="-1">4. Geo search <a class="header-anchor" href="#_4-geo-search" aria-label="Permalink to &quot;4. Geo search&quot;">​</a></h3><p>geo bounding box + radius + polygon + isochrone.</p><h3 id="_5-relevance-tuning" tabindex="-1">5. Relevance tuning <a class="header-anchor" href="#_5-relevance-tuning" aria-label="Permalink to &quot;5. Relevance tuning&quot;">​</a></h3><p>BM25 + TF-IDF + custom ranking + relevance A/B.</p><h3 id="_6-synonym-and-stemming-advanced" tabindex="-1">6. Synonym and stemming advanced <a class="header-anchor" href="#_6-synonym-and-stemming-advanced" aria-label="Permalink to &quot;6. Synonym and stemming advanced&quot;">​</a></h3><p>multi-language synonym + phonetic synonym + typo tolerance advanced + stemming advanced.</p><h3 id="_7-index-management-advanced" tabindex="-1">7. Index management advanced <a class="header-anchor" href="#_7-index-management-advanced" aria-label="Permalink to &quot;7. Index management advanced&quot;">​</a></h3><p>sharding + rolling reindex + zero downtime reindex + alias swap guard.</p><h3 id="_8-query-dsl-and-aggregation-advanced" tabindex="-1">8. Query DSL and aggregation advanced <a class="header-anchor" href="#_8-query-dsl-and-aggregation-advanced" aria-label="Permalink to &quot;8. Query DSL and aggregation advanced&quot;">​</a></h3><p>nested query + histogram aggregation + percentile aggregation + aggregation explain.</p><h2 id="_3-dogfood-search-app-v2-新規" tabindex="-1">3 dogfood search app v2 / 新規 <a class="header-anchor" href="#_3-dogfood-search-app-v2-新規" aria-label="Permalink to &quot;3 dogfood search app v2 / 新規&quot;">​</a></h2><h3 id="dogfood-search-vector-app-v2" tabindex="-1"><code>dogfood-search-vector-app</code> v2 <a class="header-anchor" href="#dogfood-search-vector-app-v2" aria-label="Permalink to &quot;`dogfood-search-vector-app` v2&quot;">​</a></h3><p>Vector kNN + HNSW + hybrid fusion + reciprocal rank fusion + recall@k walkthrough.</p><h3 id="dogfood-search-faceted-geo-app-v2" tabindex="-1"><code>dogfood-search-faceted-geo-app</code> v2 <a class="header-anchor" href="#dogfood-search-faceted-geo-app-v2" aria-label="Permalink to &quot;`dogfood-search-faceted-geo-app` v2&quot;">​</a></h3><p>Nested facet + hierarchical facet + bounding box + radius + polygon + isochrone walkthrough.</p><h3 id="dogfood-search-opensearch-app-新規" tabindex="-1"><code>dogfood-search-opensearch-app</code> 新規 <a class="header-anchor" href="#dogfood-search-opensearch-app-新規" aria-label="Permalink to &quot;`dogfood-search-opensearch-app` 新規&quot;">​</a></h3><p>OpenSearch relevance tuning + BM25 + TF-IDF + custom ranking + synonym advanced + rolling reindex walkthrough.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-test/search</span></span></code></pre></div><p>Migration guide (additive-only、 breaking change なし):</p><ul><li><a href="https://cardene777.github.io/kiwa/migrations/v1.35-to-v1.36" target="_blank" rel="noreferrer">v1.35 → v1.36 migration guide</a></li><li><a href="https://cardene777.github.io/kiwa/concepts/search-real-driver-testing" target="_blank" rel="noreferrer">Search real-driver testing SSOT concept doc</a></li></ul>',34)])])}const v=e(i,[["render",s]]);export{g as __pageData,v as default};
